#include "exotic/autonomy/agents/in_memory_repository.hpp"
#include "exotic/autonomy/agents/scheduler_bridge.hpp"
#include "exotic/autonomy/resources/in_memory_repository.hpp"
#include <cassert>
using namespace exotic::autonomy;using namespace exotic::autonomy::agents;
namespace {class Approval final:public resources::BudgetApprovalVerifier{public:bool approves(resources::GovernanceApprovalId,ProposalId,double,TimePoint,std::string&reason)override{reason="approved";return true;}};class Meter final:public resources::UsageMeter{public:resources::ResourceVector measure(const scheduler::Job&,const resources::ResourcePlan& plan,const scheduler::ExecutionResult&,std::chrono::milliseconds elapsed)override{auto actual=plan.estimate;actual.set(resources::ResourceDimension::CpuMilliseconds,static_cast<double>(elapsed.count()));actual.set(resources::ResourceDimension::ConcurrencySlots,0.0);actual.set(resources::ResourceDimension::MemoryBytes,0.0);return actual;}};class Inner final:public scheduler::ExecutionBridge{public:int calls{0};bool saw_assignment{false};scheduler::ExecutionResult execute(const scheduler::Job&,std::stop_token)override{++calls;saw_assignment=current_assignment()!=nullptr;return {true,scheduler::FailureClass::Permanent,"done"};}};}
int main(){InMemoryAgentRepository agents;AgentRegistry registry{agents};CapabilityDefinition d;d.key="execute";d.name="Execute";registry.define_capability(d);AgentIdentity a;a.identity_key="worker";a.display_name="Worker";a.health=HealthState::Healthy;a.trust=TrustLevel::Elevated;a.workload.maximum_tasks=1;a.cost.fixed_cost_usd=1.0;auto agent_id=registry.register_agent(a);registry.activate(agent_id);registry.grant_capability({agent_id,"execute",0.9,0.9,0,0,Clock::now()});AllowAllGovernanceCompatibility gov;AllowAllResourceCompatibility compat;CandidateScorer scorer{agents,registry,gov,compat};WorkAllocator allocator{agents,scorer};resources::InMemoryResourceRepository resource_repo;Approval approval;resources::ResourceGovernor governor{resource_repo,approval};resources::ResourceAccount account;account.scope=resources::AccountScope::Task;account.scope_id="job";account.name="Job";account.limits={{resources::ResourceDimension::MoneyUsd,10,8,0,0},{resources::ResourceDimension::ApiCredits,100,80,0,0},{resources::ResourceDimension::ConcurrencySlots,1,1,0,0}};auto account_id=governor.create_account(account);TaskRequirement req;req.capabilities={{"execute",0.8,0.8,true,1.0}};req.resource_account_id=account_id;req.resource_estimate={{resources::ResourceDimension::ConcurrencySlots,1.0}};req.maximum_team_cost_usd=5.0;FixedTaskRequirementPlanner planner{req};Meter meter;AgentLearningEngine learning{agents};Inner inner;AgentOrchestratedExecutionBridge bridge{agents,registry,allocator,gov,compat,governor,meter,learning,planner,inner};scheduler::Job job;job.id=10;job.proposal_id=11;job.name="agent-bridge";auto result=bridge.execute(job,{});assert(result.success);assert(inner.calls==1&&inner.saw_assignment);auto assignment=agents.find_assignment_by_job(10);assert(assignment&&assignment->status==AssignmentStatus::Completed);assert(resource_repo.load_active_reservations().empty());assert(agents.load_performance_records(agent_id,10).size()==1);return 0;}
